#' Meta-analysis through Pj
#'
#' 
#' @param data .
#' @param dataType .
#' @param study .
#' @param ai .
#' @param bi .
#' @param ci .
#' @param di .
#' @param n1i .
#' @param m1i .
#' @param sd1i .
#' @param n2i .
#' @param m2i .
#' @param sd2i .
#' @param yi .
#' @param uncertainty .
#' @param ciLower .
#' @param ciUpper .
#' @param measureDichotomous .
#' @param measureMeans .
#' @param measureGeneric .
#' @param genericInput .
#' @param inputCiLevel .
#' @param fe .
#' @param re .
#' @param level .
#' @param engine .
#' @param showFunnel .
#' @param leaveOneOut .
#' @param python .
#' @param resultType .
#' @param plotWidth .
#' @param plotHeight .
#' @param extensionDraft .
#' @param extensionCode .
#' @param extensionRevision .
#' @param extensionScriptName .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$status} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$studies} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$models} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$heterogeneity} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$forestHtml} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$forestSvg} \tab \tab \tab \tab \tab a svg \cr
#'   \code{results$extensionStatus} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$studies$asDF}
#'
#' \code{as.data.frame(results$studies)}
#'
#' @export
mzMetaPj <- function(
    data,
    dataType = "dichotomous",
    study = NULL,
    ai = NULL,
    bi = NULL,
    ci = NULL,
    di = NULL,
    n1i = NULL,
    m1i = NULL,
    sd1i = NULL,
    n2i = NULL,
    m2i = NULL,
    sd2i = NULL,
    yi = NULL,
    uncertainty = NULL,
    ciLower = NULL,
    ciUpper = NULL,
    measureDichotomous = "RR",
    measureMeans = "MD",
    measureGeneric = "GEN",
    genericInput = "variance",
    inputCiLevel = 95,
    fe = TRUE,
    re = TRUE,
    level = 95,
    engine = "d3",
    showFunnel = TRUE,
    leaveOneOut = FALSE,
    python = "jamovi",
    resultType = "html",
    plotWidth = 900,
    plotHeight = 620,
    extensionDraft,
    extensionCode = "",
    extensionRevision = 0,
    extensionScriptName = "my_extension.py") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("mzMetaPj requires jmvcore to be installed (restart may be required)")

    if ( ! missing(study)) study <- jmvcore::resolveQuo(jmvcore::enquo(study))
    if ( ! missing(ai)) ai <- jmvcore::resolveQuo(jmvcore::enquo(ai))
    if ( ! missing(bi)) bi <- jmvcore::resolveQuo(jmvcore::enquo(bi))
    if ( ! missing(ci)) ci <- jmvcore::resolveQuo(jmvcore::enquo(ci))
    if ( ! missing(di)) di <- jmvcore::resolveQuo(jmvcore::enquo(di))
    if ( ! missing(n1i)) n1i <- jmvcore::resolveQuo(jmvcore::enquo(n1i))
    if ( ! missing(m1i)) m1i <- jmvcore::resolveQuo(jmvcore::enquo(m1i))
    if ( ! missing(sd1i)) sd1i <- jmvcore::resolveQuo(jmvcore::enquo(sd1i))
    if ( ! missing(n2i)) n2i <- jmvcore::resolveQuo(jmvcore::enquo(n2i))
    if ( ! missing(m2i)) m2i <- jmvcore::resolveQuo(jmvcore::enquo(m2i))
    if ( ! missing(sd2i)) sd2i <- jmvcore::resolveQuo(jmvcore::enquo(sd2i))
    if ( ! missing(yi)) yi <- jmvcore::resolveQuo(jmvcore::enquo(yi))
    if ( ! missing(uncertainty)) uncertainty <- jmvcore::resolveQuo(jmvcore::enquo(uncertainty))
    if ( ! missing(ciLower)) ciLower <- jmvcore::resolveQuo(jmvcore::enquo(ciLower))
    if ( ! missing(ciUpper)) ciUpper <- jmvcore::resolveQuo(jmvcore::enquo(ciUpper))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(study), study, NULL),
            `if`( ! missing(ai), ai, NULL),
            `if`( ! missing(bi), bi, NULL),
            `if`( ! missing(ci), ci, NULL),
            `if`( ! missing(di), di, NULL),
            `if`( ! missing(n1i), n1i, NULL),
            `if`( ! missing(m1i), m1i, NULL),
            `if`( ! missing(sd1i), sd1i, NULL),
            `if`( ! missing(n2i), n2i, NULL),
            `if`( ! missing(m2i), m2i, NULL),
            `if`( ! missing(sd2i), sd2i, NULL),
            `if`( ! missing(yi), yi, NULL),
            `if`( ! missing(uncertainty), uncertainty, NULL),
            `if`( ! missing(ciLower), ciLower, NULL),
            `if`( ! missing(ciUpper), ciUpper, NULL))


    options <- mzMetaPjOptions$new(
        dataType = dataType,
        study = study,
        ai = ai,
        bi = bi,
        ci = ci,
        di = di,
        n1i = n1i,
        m1i = m1i,
        sd1i = sd1i,
        n2i = n2i,
        m2i = m2i,
        sd2i = sd2i,
        yi = yi,
        uncertainty = uncertainty,
        ciLower = ciLower,
        ciUpper = ciUpper,
        measureDichotomous = measureDichotomous,
        measureMeans = measureMeans,
        measureGeneric = measureGeneric,
        genericInput = genericInput,
        inputCiLevel = inputCiLevel,
        fe = fe,
        re = re,
        level = level,
        engine = engine,
        showFunnel = showFunnel,
        leaveOneOut = leaveOneOut,
        python = python,
        resultType = resultType,
        plotWidth = plotWidth,
        plotHeight = plotHeight,
        extensionDraft = extensionDraft,
        extensionCode = extensionCode,
        extensionRevision = extensionRevision,
        extensionScriptName = extensionScriptName)

    analysis <- mzMetaPjClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

